# Simpler approach: Scan all 2s, find their bounding boxes
def find_all_frames_simple(grid):
    rows, cols = len(grid), len(grid[0])

    # Collect all 2 positions
    all_2s = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

    frames = []
    used = set()

    for (r, c) in all_2s:
        if (r, c) in used:
            continue

        # Find bounding box of connected 2s (orthogonal)
        visited = set([(r, c)])
        to_visit = [(r, c)]
        while to_visit:
            curr = to_visit.pop()
            if curr in used or curr in visited:
                continue
            if not (0 <= curr[0] < rows and 0 <= curr[1] < cols) or grid[curr[0]][curr[1]] != 2:
                continue
            visited.add(curr)
            used.add(curr)

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                neighbor = (curr[0] + dr, curr[1] + dc)
                if neighbor not in visited:
                    if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] == 2:
                        to_visit.append(neighbor)

        if len(visited) < 4:
            continue

        min_r = min(x[0] for x in visited)
        max_r = max(x[0] for x in visited)
        min_c = min(x[1] for x in visited)
        max_c = max(x[1] for x in visited)

        # Verify it's a rectangular frame
        height = max_r - min_r + 1
        width = max_c - min_c + 1

        # Check all boundary cells
        frame = True
        for rr in range(min_r, max_r + 1):
            if grid[rr][min_c] != 2 or grid[rr][max_c] != 2:
                frame = False
                break

        if not frame:
            frame = True
            for cc in range(min_c, max_c + 1):
                if grid[min_r][cc] != 2 or grid[max_r][cc] != 2:
                    frame = False
                    break

        box_size = min(height, width)
        if box_size < 3:
            continue

        # Is the interior empty of 2s?
        interior = True
        for rr in range(min_r + 1, max_r):
            for cc in range(min_c + 1, max_c):
                if grid[rr][cc] == 2:
                    interior = False
                    break

            if not interior:
                break

        if not interior:
            interior = True

        print(f"Frame: rows {min_r}-{max_r}, cols {min_c}-{max_c}, box_size={box_size}, interior={interior}")

        if interior:
            frames.append((min_r, max_r, min_c, max_c, box_size))

    return frames

