def apply_transformation(grid):
    """Apply the transformation: find rectangular regions and fill with alternating colors"""
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    # Find all potential rectangles (may have duplicates)
    potential_rects = []
    for r in range(rows):
        for c in range(cols - 1):
            if grid[r][c] == 2 and grid[r][c+1] == 0:
                top = r
                while top > 0 and grid[top-1][c] == 2:
                    top -= 1

                bottom = r
                while bottom < rows - 1 and grid[bottom+1][c] == 2:
                    bottom += 1

                right = c + 1
                while right < cols:
                    if grid[top][right] == 2 or grid[bottom][right] == 2:
                        right += 1
                    else:
                        break

                r1, r2 = top + 1, bottom - 1
                c1, c2 = c + 1, right - 1

                if r1 > r2 or c1 >= c2:
                    continue

                valid = True
                for k in range(r1, r2 + 1):
                    for l in range(c1, c2):
                        if grid[k][l] != 0 and grid[k][l] != 2:
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    potential_rects.append((r1, r2, c1, c2))

    # Deduplicate
    unique_rects = set(map(lambda x: f"{x[0]},{x[1]},{x[2]},{x[3]}", potential_rects))
    rects = sorted([(int(v.split(',')[0]), int(v.split(',')[1]), int(v.split(',')[2]), int(v.split(',')[3])) for v in sorted(unique_rects)], key=lambda x: (0, -x[0]))

    # Sort by top row descending (higher top row first = shallower in grid = filled first with 3)
    rects.sort(key=lambda x: -x[0])

    print(f"Deduplicated {len(rects)} unique rectangles:\n{rects}")

    # Fill rectangles with alternating colors
    color = 3  # Start with 3
    for i, (r1, r2, c1, c2) in enumerate(rects):
        fill_color = 3 if i % 2 == 0 else 8
        for r in range(r1, r2 + 1):
            for c in range(c1, c2):
                if grid[r][c] == 0:  # Only fill 0s
                    result[r][c] = fill_color

    return result

