def find_rectangles_v4(grid):
    """Find rectangular regions bounded by full 2-edges"""
    rows, cols = len(grid), len(grid[0])

    rectangles = []

    # Find all left-vertical-boundaries: columns with 2s from top to bottom
    for c in range(cols):
        # Find segments of consecutive 2s in column c
        seg_start = row_start = -1
        for r in range(rows):
            if grid[r][c] == 2 and seg_start == -1:
                row_start = r
                seg_start = c
            elif grid[r][c] != 2:
                if row_start != -1:
                    # Found end of segment, collect more info
                    pass
                row_start = -1
            else:
                # Still in segment
                pass

        # Actually, let's find complete segments more carefully
        segs = []
        r = 0
        while r < rows:
            if grid[r][c] == 2:
                seg_end = r
                while seg_end < rows - 1 and grid[seg_end+1][c] == 2:
                    seg_end += 1
                segs.append((r, seg_end))  # (top, bottom inclusive)
                r = seg_end + 1
            else:
                r += 1

        # For each segment, find the enclosing rectangle to the right
        for r1, r2 in segs:
            # Find left boundary: column with 2s from r1 to r2
            left = c
            while left > 0:
                has_2 = all(grid[k][left-1] == 2 for k in range(r1, r2+1))
                if has_2:
                    left -= 1
                else:
                    break

            # Find right boundary: column with 2s from r1 to r2
            right = c + 1
            while right < cols:
                has_2 = all(grid[k][right] == 2 for k in range(r1, r2+1))
                if has_2:
                    right += 1
                else:
                    break

            # Interior rect: rows r1+1 to r2-1, cols left+1 to right-1
            r_int1, r_int2 = r1 + 1, r2 - 1
            c_int1, c_int2 = left + 1, right - 1

            if r_int1 > r_int2 or c_int1 >= c_int2:
                continue

            # Verify interior is 0s (allowing holes with 2s)
            valid = True
            for r in range(r_int1, r_int2 + 1):
                for c in range(c_int1, c_int2):
                    if grid[r][c] != 0 and grid[r][c] != 2:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                rects_str = f"{r_int1},{r_int2},{c_int1},{c_int2}"
                rectangles.append((rects_str, [(r, c) for c in range(c_int1, c_int2) for r in range(r_int1, r_int2+1)]))

    return rectangles

