def transform_layered(grid):
    """Apply rectangles with later ones overwriting earlier ones"""
    result = [row[:] for row in grid]

    rows, cols = len(grid), len(grid[0])
    seen = set()

    # Find all rectangles
    rects_list = []
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == 2:
                r1, r2 = r, r
                while r2 < rows - 1 and grid[r2+1][c] == 2:
                    r2 += 1

                c_right = c + 1
                while c_right < cols:
                    if grid[r1][c_right] == 2 and grid[r2][c_right] == 2:
                        c_right += 1
                    else:
                        break

                r1_int, r2_int = r1 + 1, r2 - 1
                c1_int, c2_int = c + 1, c_right - 1

                if r1_int <= r2_int and c1_int <= c2_int - 1:
                    rect_key = f"{r1_int},{r2_int},{c1_int},{c2_int}"
                    if rect_key not in seen:
                        seen.add(rect_key)
                        rects_list.append((r1_int, r2_int, c1_int, c2_int))

                r = r2 + 1
            else:
                r += 1

    # Sort by top row ASCENDING (earliest to be painted first = gets overwritten later)
    # Then later ones (higher top row) overwrite
    rects_sorted = sorted(rects_list, key=lambda x: x[0])

    # Layer 1 gets color 3, layer 2 gets color 8, layer 3 gets color 3, etc.
    # But we want to OVERLAY, so lower layers (earlier) should be 3/8
    # and higher layers (later) should overwrite with reversed or same?

    # Actually, looking at DEMO: top gets 3, bottom gets 8
    # Top-most rect (lowest index) = 3
    # Bottom-most rect (highest index) = 8
    # So index 0 gets 3, index 1 gets 8, index 2 gets 3, index 3 gets 8

    for i, (r1, r2, c1, c2) in enumerate(rects_sorted):
        fill_color = 3 if i % 2 == 0 else 8
        for r in range(r1, r2 + 1):
            for c in range(c1, c2):
                if grid[r][c] == 0:  # Only paint on 0s
                    result[r][c] = fill_color

    return result

