def transform(grid):
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    seen = set()

    rects_list = []
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == 2:
                r1, r2 = r, r
                while r2 < rows - 1 and grid[r2+1][c] == 2:
                    r2 += 1

                c_right = c + 1
                while c_right < cols:
                    if grid[r1][c_right] == 2 and grid[r2][c_right] == 2:
                        c_right += 1
                    else:
                        break

                r1_int, r2_int = r1 + 1, r2 - 1
                c1_int, c2_int = c + 1, c_right - 1

                if r1_int <= r2_int and c1_int <= c2_int - 1:
                    rect_key = f"{r1_int},{r2_int},{c1_int},{c2_int}"
                    if rect_key not in seen:
                        seen.add(rect_key)
                        rects_list.append((r1_int, r2_int, c1_int, c2_int))

                r = r2 + 1
            else:
                r += 1

    rects_sorted = sorted(rects_list, key=lambda x: x[0])

    for i, (r1, r2, c1, c2) in enumerate(rects_sorted):
        fill_color = 3 if i % 2 == 0 else 8
        for r in range(r1, r2 + 1):
            for c in range(c1, c2):
                if grid[r][c] == 0:
                    result[r][c] = fill_color

    return result

