def find_enclosed_regions(grid):
    """Find regions of 0s that are bounded on one side by 2s and on the other by grid edge or other 0s"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    regions = []

    # Find candidate starting points (0s on left side that have 2s to their right)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                # Check if this could be start of enclosed region (has 2 to the right and 0s extending rightward)
                k = c
                while k < cols - 1 and grid[r][k] == 0:
                    k += 1
                if k < cols and grid[r][k] == 2:
                    # This is a potential start
                    # Flood fill to the right to find the extent
                    region = []
                    to_visit = [(r, c)]
                    while to_visit:
                        fr, fc = to_visit.pop()
                        if visited[fr][fc]:
                            continue
                        visited[fr][fc] = True
                        region.append((fr, fc))
                        if fr - 1 >= 0:
                            if grid[fr-1][fc] == 0 and not visited[fr-1][fc]:
                                to_visit.append((fr-1, fc))
                        if fr + 1 < rows:
                            if grid[fr+1][fc] == 0 and not visited[fr+1][fc]:
                                to_visit.append((fr+1, fc))
                        if fc + 1 < cols:
                            if grid[fr][fc+1] == 0 and not visited[fr][fc+1]:
                                to_visit.append((fr, fc+1))
                        if fc - 1 >= 0:
                            if grid[fr][fc-1] == 0 and not visited[fr][fc-1]:
                                to_visit.append((fr, fc-1))
                    if len(region) > 0:
                        regions.append(region)

    return regions

