def transform(grid):
    """
    Fill enclosed hollow regions with alternating colors.
    Pattern from Demo 4: even-ranked regions get color 8, odd-ranked get color 4.
    Regions sorted by top row ascending, then left column.
    """
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    seen = set()

    # Find all 0-regions that don't touch the boundary
    compartments = []
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == 2:
                r1, r2 = r, r
                while r2 < rows - 1 and grid[r2+1][c] == 2:
                    r2 += 1

                c_right = c + 1
                while c_right < cols:
                    if grid[r1][c_right] == 2 and grid[r2][c_right] == 2:
                        c_right += 1
                    else:
                        break

                r1_int, r2_int = r1 + 1, r2 - 1
                c1_int, c2_int = c + 1, c_right - 1

                if r1_int <= r2_int and c1_int <= c2_int - 1:
                    rect_key = f"{r1_int},{r2_int},{c1_int},{c2_int}"
                    if rect_key not in seen:
                        seen.add(rect_key)
                        compartments.append((r1_int, r2_int, c1_int, c2_int))

                r = r2 + 1
            else:
                r += 1

    # Sort by top row, then left column
    compartments_sorted = sorted(compartments, key=lambda x: x[0])

    # Fill with alternating colors: even rank -> 8, odd rank -> 4
